import {e,safeURL} from './ui.mjs?v=20261116editor';
import {homeModuleLabels} from './editorial-model.mjs?v=20261116editor';
export function editorialEditor(tab,d,{input,block}){
 const at=path=>path.split('.').reduce((value,key)=>value?.[key],d);
 const image=(path,label='Imagen')=>`<div class="editor-image">${at(path)?`<img src="${safeURL(at(path))}" alt="Vista previa de ${e(label)}" loading="lazy">`:''}<div>${input(path,label+' · URL')}<label class="editor-upload">Subir o reemplazar<input type="file" data-upload-path="${e(path)}" accept="image/jpeg,image/png,image/webp"></label></div></div>`;
 const button=(path)=>input(path+'.buttonLabel','Texto del botón')+input(path+'.buttonHref','Destino del botón · página interna o HTTPS');
 const photos=(path,max)=>`${(at(path)||[]).map((photo,i)=>`<div class="editor-photo-row">${image(path+'.'+i+'.photo','Fotografía '+(i+1))}${input(path+'.'+i+'.'+(path==='clients.items'?'alt':'caption'),'Descripción de la fotografía',{area:true})}${path==='clients.items'?input(path+'.'+i+'.caption','Texto que acompaña la foto',{area:true})+input(path+'.'+i+'.published','Mostrar fotografía',{check:true}):''}<button type="button" class="text-button danger" data-delete-photo="${path}" data-index="${i}">Quitar fotografía</button></div>`).join('')}<button type="button" class="button button-outline" data-add-photo="${path}" ${(at(path)||[]).length>=max?'disabled':''}>Agregar fotografía · ${(at(path)||[]).length}/${max}</button>`;
 const faq=()=>input('faqConfig.title','Título del módulo')+input('faqConfig.intro','Descripción',{area:true})+d.faq.map((q,i)=>`<details class="editor-item"><summary>${e(q.question||'Nueva pregunta')}</summary>${input(`faq.${i}.category`,'Categoría')+input(`faq.${i}.question`,'Pregunta')+input(`faq.${i}.answer`,'Respuesta',{area:true})}<button type="button" class="text-button danger" data-delete-faq="${i}">Quitar pregunta</button></details>`).join('')+'<button type="button" class="button button-outline" data-new-faq>Agregar pregunta</button>';
 const process=()=>input('processTitle','Frase principal',{area:true})+d.process.map((step,i)=>block('Etapa '+(i+1),image(`process.${i}.image`)+input(`process.${i}.imageAlt`,'Descripción de imagen')+input(`process.${i}.title`,'Título')+input(`process.${i}.text`,'Descripción',{area:true})+input(`process.${i}.items`,'Puntos · uno por línea',{lines:true}))).join('');
 const module=id=>{
  if(id==='statement')return input('statement.text','Frase de presentación',{area:true})+button('statement');
  if(id==='properties')return '<p>Usa el catálogo activo. Edita aquí su encabezado y botón; las propiedades se gestionan en su sección.</p>'+input('widgets.properties.title','Título')+button('widgets.properties');
  if(id==='reviews')return '<p>Usa las reseñas aprobadas. Los comentarios se moderan en Reseñas.</p>'+input('widgets.reviews.title','Título')+input('widgets.reviews.intro','Descripción · vacío muestra el total de reseñas');
  if(id==='clients')return input('clients.title','Título')+input('clients.intro','Descripción',{area:true})+photos('clients.items',100);
  if(id==='process')return process();
  if(id==='metrics')return input('metrics.title','Título')+input('metrics.intro','Descripción',{area:true})+image('metrics.image','Imagen de fondo')+input('metrics.imageAlt','Descripción de imagen')+d.metrics.items.map((item,i)=>block('Cifra '+(i+1),input(`metrics.items.${i}.label`,'Descripción')+input(`metrics.items.${i}.source`,'Origen del número',{choices:{manual:'Número manual',properties:'Total de propiedades activas',team:'Integrantes del equipo',services:'Servicios',locations:'Zonas del catálogo'}})+input(`metrics.items.${i}.value`,'Número · se usa al elegir Número manual',{number:true}))).join('');
  if(id==='living')return input('living.title','Frase principal',{area:true})+button('living')+d.living.photos.map((photo,i)=>block('Imagen '+(i+1),image(`living.photos.${i}.photo`)+input(`living.photos.${i}.alt`,'Descripción de imagen'))).join('');
  if(id==='faq')return faq();
  if(id==='transactions')return input('transactions.title','Título')+input('transactions.intro','Descripción',{area:true})+input('transactions.visible','Mostrar el historial en el sitio',{check:true})+'<p>Las operaciones y las cancelaciones se gestionan en Propiedades. Este interruptor oculta o muestra el módulo completo.</p>';
  if(id==='journal')return input('widgets.journal.title','Título')+input('widgets.journal.intro','Descripción',{area:true});
  return '';
 };
 if(tab==='home')return block('Portada · primera imagen',image('home.photo','Imagen principal')+input('home.photoAlt','Descripción de la imagen')+input('home.title','Frase principal',{area:true})+input('home.intro','Descripción',{area:true})+button('home'))+block('Orden y visibilidad',`<p>Sube o baja cada módulo. Ocultarlo conserva su contenido.</p><div class="module-sort">${d.home.modules.map((id,i)=>`<div><span>${e(homeModuleLabels[id]||id)}</span><label class="consent"><input type="checkbox" data-module-visible="${id}" ${d.home.hiddenModules.includes(id)?'':'checked'}>Visible</label><button type="button" class="text-button" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir ${e(homeModuleLabels[id])}">↑</button><button type="button" class="text-button" data-move="${i}" data-dir="1" ${i===d.home.modules.length-1?'disabled':''} aria-label="Bajar ${e(homeModuleLabels[id])}">↓</button></div>`).join('')}</div><label>Agregar módulo<select id="add-module"><option value="">Elige un módulo</option>${Object.keys(homeModuleLabels).filter(id=>!d.home.modules.includes(id)).map(id=>`<option value="${id}">${e(homeModuleLabels[id])}</option>`).join('')}</select></label>`)+d.home.modules.map(id=>`<details class="editor-module"><summary>${e(homeModuleLabels[id])}<span>${d.home.hiddenModules.includes(id)?'Oculto':'Visible'}</span></summary><div>${module(id)}</div></details>`).join('');
 if(tab==='team')return block('Presentación',input('team.title','Título')+input('team.intro','Descripción',{area:true})+input('team.paragraphs','Historia · un párrafo por línea',{lines:true}))+`<details class="editor-module"><summary>Portada y fotografías del equipo</summary><div>${image('team.cover','Portada')+input('team.coverAlt','Descripción de la portada')+input('team.photosTitle','Título de las fotos del equipo')+d.team.photos.map((_,i)=>image(`team.photos.${i}`,'Foto del equipo '+(i+1))).join('')}</div></details>`+d.team.members.map((person,i)=>`<details class="editor-module"><summary>${e(person.name)}</summary><div>${input(`team.members.${i}.name`,'Nombre')+image(`team.members.${i}.photo`,'Foto de perfil')+input(`team.members.${i}.bio`,'Descripción',{area:true})+input(`team.members.${i}.contactLabel`,'Texto del botón de contacto')+input(`team.members.${i}.contact`,'Destino del contacto HTTPS')+input(`team.members.${i}.phone`,'Teléfono')}</div></details>`).join('')+`<details class="editor-module"><summary>Cómo te acompañamos</summary><div>${input('team.approachTitle','Título del módulo')+d.team.approach.map((_,i)=>block('Contenido '+(i+1),input(`team.approach.${i}.title`,'Título')+input(`team.approach.${i}.text`,'Descripción',{area:true}))).join('')}</div></details><details class="editor-module"><summary>CAPPERS · hasta 8 fotos</summary><div>${input('team.galleryTitle','Título')+input('team.galleryIntro','Descripción',{area:true})+photos('team.gallery',8)}</div></details><details class="editor-module"><summary>Novatos · hasta 2 fotos</summary><div>${input('team.nationalAward.title','Título')+input('team.nationalAward.description','Descripción',{area:true})+photos('team.nationalAward.photos',2)}</div></details>`+block('Mostrar módulos',Object.entries({cover:'Portada',approach:'Cómo te acompañamos',photos:'Fotos del equipo',cappers:'CAPPERS',national:'Novatos'}).map(([id,label])=>`<label class="consent"><input type="checkbox" data-team-visible="${id}" ${d.team.hiddenSections.includes(id)?'':'checked'}>${label}</label>`).join(''));
 if(tab==='process')return process();if(tab==='faq')return faq();return null;
}
